observation.command:
curl -s "http://localhost:8080/supabase-events?limit=500" 2>/dev/null | node -e "
const data = JSON.parse(require('fs').readFileSync(0, 'utf-8'));
console.log('=== FINAL VERIFICATION ===');
console.log('');
console.log('Total events returned:', data.count);
console.log('');
console.log('Source counts:');
Object.entries(data.source_counts).forEach(([source, count]) => {
  console.log('  ' + source + ': ' + count);
});
console.log('');
console.log('Kulturhuset events:', data.events?.filter(e => e.source === 'kulturhuset').length || 0);
console.log('');
console.log('Sample Kulturhuset events:');
data.events?.filter(e => e.source === 'kulturhuset').slice(0, 5).forEach(e => {
  console.log('  ' + e.date + ' ' + e.title.substring(0, 40));
});
"

